import{_ as e,o as d,c as r,O as a}from"./chunks/framework.57749cb7.js";const c=JSON.parse('{"title":"Coding Agent、Computer Use 与 A2A","description":"Coding Agent、Computer Use 与 A2A：三者分别解决什么、代码智能体的执行沙箱与权限、Computer Use 的视觉操作循环与风险、A2A 的 Agent 间协作协议。","frontmatter":{"description":"Coding Agent、Computer Use 与 A2A：三者分别解决什么、代码智能体的执行沙箱与权限、Computer Use 的视觉操作循环与风险、A2A 的 Agent 间协作协议。","tags":["AI Agent","大模型"]},"headers":[],"relativePath":"backend/AI-Agent/12-CodingAgent与A2A.md","filePath":"backend/AI-Agent/12-CodingAgent与A2A.md","lastUpdated":1793332732000}'),n={name:"backend/AI-Agent/12-CodingAgent与A2A.md"};function o(s,t,l,i,g,h){return d(),r("div",null,t[0]||(t[0]=[a(`<h1 id="coding-agent、computer-use-与-a2a" tabindex="-1">Coding Agent、Computer Use 与 A2A <a class="header-anchor" href="#coding-agent、computer-use-与-a2a" aria-label="Permalink to &quot;Coding Agent、Computer Use 与 A2A&quot;">​</a></h1><blockquote><p>这三个是 2025 年后最常被问的「新范式」，但经常被混为一谈。一句话分清： <strong>Coding Agent = 改代码</strong>；<strong>Computer Use = 操作图形界面</strong>；<strong>A2A = Agent 之间说话</strong>。</p></blockquote><h2 id="一、三者定位" tabindex="-1">一、三者定位 <a class="header-anchor" href="#一、三者定位" aria-label="Permalink to &quot;一、三者定位&quot;">​</a></h2><table><thead><tr><th></th><th>Coding Agent</th><th>Computer Use</th><th>A2A</th></tr></thead><tbody><tr><td>操作对象</td><td>代码仓库（文件 + 终端）</td><td>屏幕（鼠标键盘 + 截图）</td><td>别的 Agent</td></tr><tr><td>接口</td><td>文件读写 + shell</td><td>视觉模型 + 点击/输入</td><td>任务委派协议</td></tr><tr><td>典型产品</td><td>Claude Code、Codex CLI、Cursor</td><td>各家的 computer-use 模型</td><td>Google 主导的 A2A</td></tr><tr><td>核心难点</td><td>沙箱与验证</td><td>视觉定位与纠错</td><td>身份、权限、结果契约</td></tr></tbody></table><h2 id="二、coding-agent-本质是「带工具的循环」" tabindex="-1">二、Coding Agent：本质是「带工具的循环」 <a class="header-anchor" href="#二、coding-agent-本质是「带工具的循环」" aria-label="Permalink to &quot;二、Coding Agent：本质是「带工具的循环」&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">读需求 → 找文件 → 改代码 → 跑测试 → 看报错 → 再改（循环）→ 提交</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">读需求 → 找文件 → 改代码 → 跑测试 → 看报错 → 再改（循环）→ 提交</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>它之所以能工作，靠的是<strong>闭环反馈</strong>：有测试、有编译器、有 lint —— 这些是可靠的「对错信号」，比纯聊天可靠得多。</p><h3 id="工程上的四个关键设计" tabindex="-1">工程上的四个关键设计 <a class="header-anchor" href="#工程上的四个关键设计" aria-label="Permalink to &quot;工程上的四个关键设计&quot;">​</a></h3><table><thead><tr><th>设计</th><th>为什么</th></tr></thead><tbody><tr><td><strong>工具最小化</strong></td><td>只给 <code>read/write/run</code> 几个工具，工具越多越容易乱用</td></tr><tr><td><strong>沙箱隔离</strong></td><td>容器内运行，限制网络与文件系统（否则一条 <code>rm -rf</code> 就完了）</td></tr><tr><td><strong>上下文管理</strong></td><td>代码库太大必须做检索 + 摘要，不能全塞</td></tr><tr><td><strong>人在环上</strong></td><td>提交前 diff 审核；危险命令（force push、删库）必须拦</td></tr></tbody></table><h3 id="为什么它比聊天式生成靠谱" tabindex="-1">为什么它比聊天式生成靠谱 <a class="header-anchor" href="#为什么它比聊天式生成靠谱" aria-label="Permalink to &quot;为什么它比聊天式生成靠谱&quot;">​</a></h3><table><thead><tr><th>纯生成</th><th>Agent 式</th></tr></thead><tbody><tr><td>一次输出，错了不知道</td><td>跑测试 → 看错误 → 修正</td></tr><tr><td>不了解仓库现状</td><td>先读文件再改</td></tr><tr><td>无法验证</td><td>有编译/lint/测试作为判据</td></tr></tbody></table><h2 id="三、computer-use-视觉闭环" tabindex="-1">三、Computer Use：视觉闭环 <a class="header-anchor" href="#三、computer-use-视觉闭环" aria-label="Permalink to &quot;三、Computer Use：视觉闭环&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">截图 → 模型识别界面元素 → 输出动作（click/type/scroll）→ 执行 → 再截图</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">截图 → 模型识别界面元素 → 输出动作（click/type/scroll）→ 执行 → 再截图</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>难点不在动作，在「看懂 + 纠错」</strong>：</p><table><thead><tr><th>难点</th><th>说明</th></tr></thead><tbody><tr><td>坐标定位</td><td>模型给的是像素坐标，分辨率/缩放变化会偏</td></tr><tr><td>状态确认</td><td>点完之后要判断「有没有生效」，不能盲点下一步</td></tr><tr><td>长任务漂移</td><td>二三十步后容易跑偏，需要定期截图自我校验</td></tr><tr><td>速度与成本</td><td>每步一张图，token 消耗极高</td></tr></tbody></table><h3 id="风险明显更高" tabindex="-1">风险明显更高 <a class="header-anchor" href="#风险明显更高" aria-label="Permalink to &quot;风险明显更高&quot;">​</a></h3><ul><li><strong>不可逆操作</strong>（删文件、转账、发帖）—— 必须有人确认；</li><li><strong>凭据泄露</strong> —— 屏幕上可能显示密码、验证码；</li><li><strong>提示注入</strong> —— 网页内容里藏指令，模型可能照做。</li></ul><blockquote><p>所以 Computer Use 目前主要用在：<strong>受控的重复性操作</strong>（填表、批量导出）、<strong>测试与自动化</strong>，而不是开放式的日常操作。</p></blockquote><h2 id="四、a2a-agent-之间怎么协作" tabindex="-1">四、A2A：Agent 之间怎么协作 <a class="header-anchor" href="#四、a2a-agent-之间怎么协作" aria-label="Permalink to &quot;四、A2A：Agent 之间怎么协作&quot;">​</a></h2><p>单 Agent 干不了的事，拆给多个 Agent —— 但<strong>不是「让模型互相发消息」那么简单</strong>，需要协议：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">客户端 Agent  →（任务委派）→  远程 Agent</span></span>
<span class="line"><span style="color:#e1e4e8;">              ←（状态/结果）←</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">客户端 Agent  →（任务委派）→  远程 Agent</span></span>
<span class="line"><span style="color:#24292e;">              ←（状态/结果）←</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="协议要解决的四个问题" tabindex="-1">协议要解决的四个问题 <a class="header-anchor" href="#协议要解决的四个问题" aria-label="Permalink to &quot;协议要解决的四个问题&quot;">​</a></h3><table><thead><tr><th>问题</th><th>做法</th></tr></thead><tbody><tr><td><strong>怎么发现对方能力</strong></td><td>Agent Card（声明技能、输入输出、鉴权方式）</td></tr><tr><td><strong>怎么派任务</strong></td><td>Task 对象：id、状态（submitted/working/completed/failed）、产物</td></tr><tr><td><strong>怎么传中间进度</strong></td><td>状态更新 + 流式事件</td></tr><tr><td><strong>怎么鉴权</strong></td><td>复用 OAuth2 / mTLS，按用户身份透传</td></tr></tbody></table><h3 id="与-mcp-的区别-高频混淆点" tabindex="-1">与 MCP 的区别（高频混淆点） <a class="header-anchor" href="#与-mcp-的区别-高频混淆点" aria-label="Permalink to &quot;与 MCP 的区别（高频混淆点）&quot;">​</a></h3><table><thead><tr><th></th><th>MCP</th><th>A2A</th></tr></thead><tbody><tr><td>连接的是</td><td><strong>工具/数据源</strong>（模型 → 能力）</td><td><strong>另一个 Agent</strong>（Agent → Agent）</td></tr><tr><td>交互粒度</td><td>一次工具调用</td><td>一个任务（可能多轮）</td></tr><tr><td>能否自主决策</td><td>不能（只是执行）</td><td>能（对方也是 Agent）</td></tr></tbody></table><p><strong>一句记忆法</strong>：<strong>MCP 是「给 Agent 装手」，A2A 是「让 Agent 找人」</strong>。</p><h2 id="五、多-agent-编排的三种形态" tabindex="-1">五、多 Agent 编排的三种形态 <a class="header-anchor" href="#五、多-agent-编排的三种形态" aria-label="Permalink to &quot;五、多 Agent 编排的三种形态&quot;">​</a></h2><table><thead><tr><th>形态</th><th>说明</th><th>适用</th></tr></thead><tbody><tr><td><strong>Supervisor</strong></td><td>一个主 Agent 分派 + 汇总</td><td>最常见，好调试</td></tr><tr><td><strong>Pipeline</strong></td><td>流水线，每个 Agent 一道工序</td><td>步骤固定的流程</td></tr><tr><td><strong>Swarm / 去中心</strong></td><td>Agent 之间直接交接</td><td>灵活但难排查</td></tr></tbody></table><p><strong>实践建议</strong>：<strong>先用 Supervisor</strong>。去中心化的多 Agent 看起来酷，但出了问题很难定位是哪个 Agent 的锅。</p><h2 id="六、落地时的四个坑" tabindex="-1">六、落地时的四个坑 <a class="header-anchor" href="#六、落地时的四个坑" aria-label="Permalink to &quot;六、落地时的四个坑&quot;">​</a></h2><ol><li><strong>上下文在 Agent 之间丢失</strong>：交接时必须显式传「目标 + 已知事实 + 约束」，不能假设对方知道前文；</li><li><strong>无限互调</strong>：A 让 B 做，B 又转回 A —— 要设<strong>最大跳数</strong>与<strong>循环检测</strong>；</li><li><strong>成本爆炸</strong>：每次交接都是一次完整上下文，链路一长费用指数上升；</li><li><strong>责任不清</strong>：出错了要能追到具体 Agent 与具体步骤 → <strong>trace 必须贯穿</strong>。</li></ol><h2 id="七、速查" tabindex="-1">七、速查 <a class="header-anchor" href="#七、速查" aria-label="Permalink to &quot;七、速查&quot;">​</a></h2><table><thead><tr><th>问题</th><th>答案</th></tr></thead><tbody><tr><td>Coding Agent 为什么靠谱</td><td>有测试/编译/lint 作为可靠反馈，形成闭环</td></tr><tr><td>Coding Agent 必须有什么</td><td>沙箱、最小工具集、diff 审核</td></tr><tr><td>Computer Use 的核心难点</td><td>视觉定位 + 状态确认 + 长任务漂移</td></tr><tr><td>Computer Use 最大风险</td><td>不可逆操作与凭据泄露</td></tr><tr><td>A2A 解决什么</td><td>Agent 之间的任务委派与结果契约</td></tr><tr><td>MCP 和 A2A 的区别</td><td>MCP 连工具，A2A 连 Agent</td></tr><tr><td>多 Agent 首选哪种</td><td>Supervisor（好调试）</td></tr><tr><td>多 Agent 最常见事故</td><td>上下文丢失与无限互调</td></tr></tbody></table>`,33)]))}const A=e(n,[["render",o]]);export{c as __pageData,A as default};
